package org.humanjourney.core.progress;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
class ProgressCapacityTest {
 static JsonObject synthetic(int count,int edgeCount)throws Exception{var root=ProgressGraphTest.example();var template=root.getAsJsonArray("nodes").get(0).getAsJsonObject();var nodes=new JsonArray();for(int i=0;i<count;i++){var n=template.deepCopy();n.addProperty("id","synthetic:n"+i);n.addProperty("era",i<count/2?"era_0":"era_1");n.addProperty("title","Synthetic milestone "+i);n.addProperty("description","Synthetic read-only large-canvas fixture.");n.addProperty("x",i%32*200);n.addProperty("y",i/32*90);n.add("completion",ProgressGraphTest.condition("#n"+i));n.add("requires",new JsonArray());nodes.add(n);}root.add("nodes",nodes);var edges=new JsonArray();outer:for(int distance=1;distance<count;distance++)for(int i=0;i+distance<count;i++){if(edges.size()==edgeCount)break outer;var edge=new JsonObject();edge.addProperty("from","synthetic:n"+i);edge.addProperty("to","synthetic:n"+(i+distance));edge.addProperty("kind",distance==1?"prerequisite":"visual");if(distance==1)nodes.get(i+distance).getAsJsonObject().getAsJsonArray("requires").add("synthetic:n"+i);edges.add(edge);}root.add("connections",edges);return root;}
 @Test @Timeout(30) void maximumGraphParseProjectionAndBoundedTransferBenchmark()throws Exception{String text=synthetic(512,2048).toString();double[] parse=new double[5],projection=new double[5],transfer=new double[5];ProgressGraph graph=null;ProgressView view=null;List<ProgressPackets.Frame> frames=null;for(int i=-2;i<5;i++){long t=System.nanoTime();graph=ProgressGraph.parse(ProgressJson.read(text),id->true);double a=(System.nanoTime()-t)/1e6;t=System.nanoTime();view=ProgressGraphTest.view(graph,Map.of());double b=(System.nanoTime()-t)/1e6;t=System.nanoTime();frames=ProgressPackets.frames(new UUID(0,160),1,view);double c=(System.nanoTime()-t)/1e6;if(i>=0){parse[i]=a;projection[i]=b;transfer[i]=c;}}assertEquals(512,graph.nodes().size());assertEquals(2048,graph.connections().size());assertTrue(frames.size()<=128);var mirror=new ProgressMirror();for(var f:frames)mirror.accept(f);assertEquals(view,mirror.view());Arrays.sort(parse);Arrays.sort(projection);Arrays.sort(transfer);var report=new LinkedHashMap<String,Object>();report.put("nodes",512);report.put("connections",2048);report.put("parse_validate_envelope_median_ms",parse[2]);report.put("projection_median_ms",projection[2]);report.put("transfer_prepare_median_ms",transfer[2]);report.put("snapshot_utf8_bytes",view.json().getBytes(java.nio.charset.StandardCharsets.UTF_8).length);report.put("fragments",frames.size());report.put("method","2warmups/median5; synthetic512nodes/2048edges; no client/world/gameplay/TPS/FPS measurement");var path=ProgressGraphTest.project().resolve("build/reports/civilization-progress-benchmark.json");Files.createDirectories(path.getParent());Files.writeString(path,new GsonBuilder().setPrettyPrinting().create().toJson(report));}
 @Test void nodeAndConnectionLimitsRejectOneAbove()throws Exception{assertThrows(IllegalArgumentException.class,()->ProgressGraphTest.parse(synthetic(513,0)));assertThrows(IllegalArgumentException.class,()->ProgressGraphTest.parse(synthetic(512,2049)));}
 @Test void oversizedSanitisedUtf8EnvelopeRejectsBeforeRuntimeTransfer()throws Exception{var root=synthetic(512,2048);for(var e:root.getAsJsonArray("nodes")){var n=e.getAsJsonObject();n.addProperty("title","汉".repeat(128));n.addProperty("description","汉".repeat(1300));}var error=assertThrows(IllegalArgumentException.class,()->ProgressGraphTest.parse(root));assertTrue(error.getMessage().contains("2MiB"),error.getMessage());}
 @Test void boundedDepthProtectsResourceAndClientParsing(){String deep="[".repeat(40)+"0"+"]".repeat(40);assertThrows(IllegalArgumentException.class,()->ProgressJson.read(deep));assertThrows(IllegalArgumentException.class,()->ProgressView.parse(deep));assertDoesNotThrow(()->ProgressJson.read("{\"text\":\"[".repeat(1)+"[".repeat(100)+"\"}"));}
 @Test void conservativeLabelBudgetCountsJsonEscapingAndOpaqueHiddenLabels(){assertEquals("<".repeat(10),ProgressView.worstLabel("<".repeat(10)));assertEquals("Unrevealed prerequisite",ProgressView.worstLabel("A"));assertEquals("汉".repeat(20),ProgressView.worstLabel("汉".repeat(20)));}
}
